 function tick(now){if(visible&&!document.hidden&&now-last>50){draw(now/1000);last=now;}frame=requestAnimationFrame(tick);}
 function restart(){cancelAnimationFrame(frame);showScene(index,false);if(!motion.matches)frame=requestAnimationFrame(tick);startCycle();}
 document.querySelectorAll('.research-rail [data-scene]').forEach((a,i)=>{
  const preview=()=>{showScene(i);startCycle();};a.addEventListener('pointerenter',preview);a.addEventListener('focus',preview);
 });
