const reportMarkdown = window.markdownit({html: false, breaks: false, linkify: false, typographer: false});

function reportFormula(source, display) {
  const rendered = katex.renderToString(source, {
    displayMode: display, throwOnError: false, trust: false,
    strict: 'ignore', maxExpand: 1000, output: 'htmlAndMathml'
  });
  return display ? `<div class="report-equation" tabindex="0">${rendered}</div>\n` : rendered;
}

// Parse mathematics before Markdown can interpret TeX underscores and escapes.
reportMarkdown.inline.ruler.before('escape', 'report_math', (state, silent) => {
  const start = state.pos, text = state.src;
  let open, close;
  if (text.startsWith('\\(', start)) { open = '\\('; close = '\\)'; }
  else if (text[start] === '$' && text[start + 1] !== '$' && !/\s/.test(text[start + 1] || ' ')) { open = close = '$'; }
  else return false;
  let end = start + open.length;
  while ((end = text.indexOf(close, end)) !== -1) {
    let escapes = 0;
    for (let i = end - 1; i >= 0 && text[i] === '\\'; i--) escapes++;
    if (escapes % 2 === 0) break;
    end += close.length;
  }
  if (end === -1 || end === start + open.length) return false;
  if (close === '$' && (/\s/.test(text[end - 1]) || /\d/.test(text[end + 1] || ''))) return false;
  const source = text.slice(start + open.length, end);
  if (source.includes('\n\n')) return false;
  if (!silent) { const token = state.push('report_math_inline', 'math', 0); token.content = source; }
  state.pos = end + close.length;
  return true;
});
reportMarkdown.renderer.rules.report_math_inline = (tokens, i) => reportFormula(tokens[i].content, false);

reportMarkdown.block.ruler.before('fence', 'report_math_block', (state, startLine, endLine, silent) => {
  const first = state.src.slice(state.bMarks[startLine] + state.tShift[startLine], state.eMarks[startLine]);
  const open = first.startsWith('$$') ? '$$' : first.startsWith('\\[') ? '\\[' : null;
  if (!open || state.sCount[startLine] - state.blkIndent >= 4) return false;
  const close = open === '$$' ? '$$' : '\\]';
  let line = startLine, content = first.slice(open.length), end = content.indexOf(close);
  while (end === -1 && ++line < endLine) {
    content += '\n' + state.src.slice(state.bMarks[line] + state.tShift[line], state.eMarks[line]);
    end = content.indexOf(close);
  }
  if (end === -1 || content.slice(end + close.length).trim()) return false;
  if (silent) return true;
  const token = state.push('report_math_block', 'math', 0);
  token.content = content.slice(0, end).trim(); token.block = true; token.map = [startLine, line + 1];
  state.line = line + 1;
  return true;
}, {alt: ['paragraph', 'reference', 'blockquote', 'list']});
reportMarkdown.renderer.rules.report_math_block = (tokens, i) => reportFormula(tokens[i].content, true);

function reportFile(target, env) {
  if (/^(?:[a-z][\w+.-]*:|\/\/|#)/i.test(target)) return null;
  try {
    const url = new URL(target, 'https://report.invalid/' + env.path);
    if (url.origin !== 'https://report.invalid') return null;
    const path = decodeURIComponent(url.pathname.slice(1));
    return current.files.find(file => file.path === path) || null;
  } catch { return null; }
}
reportMarkdown.renderer.rules.image = (tokens, i, options, env) => {
  const token = tokens[i], file = reportFile(token.attrGet('src'), env);
  const alt = reportMarkdown.renderer.renderInlineAsText(token.children || [], options, env);
  if (!file || !file.mime.startsWith('image/')) return `<span class="report-missing-image">${esc(alt || token.attrGet('src'))}</span>`;
  return `<img src="${esc(uri(file))}" alt="${esc(alt)}" decoding="async">`;
};

reportMarkdown.renderer.rules.table_open = () => '<div class="report-table" tabindex="0" role="region" aria-label="Report table"><table>\n';
reportMarkdown.renderer.rules.table_close = () => '</table></div>\n';
reportMarkdown.renderer.rules.heading_open = (tokens, i, options, env, self) => {
  const text = tokens[i + 1]?.content || '';
  const slug = text.toLowerCase().replace(/[^\p{L}\p{N}\s_-]/gu, '').trim().replace(/\s+/g, '-');
  const used = env.headings || (env.headings = new Map());
  const count = used.get(slug) || 0; used.set(slug, count + 1);
  tokens[i].attrSet('id', 'report-' + slug + (count ? '-' + count : ''));
  return self.renderToken(tokens, i, options);
};
reportMarkdown.renderer.rules.link_open = (tokens, i, options, env, self) => {
  const token = tokens[i], href = token.attrGet('href') || '', file = reportFile(href, env);
  let button;
  if (href.startsWith('#')) button = `<button type="button" class="report-link" data-report-anchor="${esc(href.slice(1))}">`;
  else if (file) button = `<button type="button" class="report-link" data-report-file="${esc(file.path)}">`;
  (env.links || (env.links = [])).push(Boolean(button));
  if (button) return button;
  if (!/^(https?:|mailto:)/i.test(href)) {
    token.attrs = (token.attrs || []).filter(([name]) => name !== 'href');
  } else { token.attrSet('target', '_blank'); token.attrSet('rel', 'noopener noreferrer'); }
  return self.renderToken(tokens, i, options);
};
