/* Fetch original reports and code only when a reader opens the corresponding file. */
const fileDownloads = new Map();
let fileRequest = 0;

async function openFile(path) {
  const owner = current, file = owner.files.find(item => item.path === path), request = ++fileRequest;
  if (!file || file.mime.startsWith('image/') || path.endsWith('.npz') || file.text !== undefined) {
    renderFile(path);
    return;
  }
  modal(path, '<p role="status">' + (language === 'en' ? 'Loading file…' : '正在加载文件…') + '</p>', '', file);
  if (!fileDownloads.has(file.url)) {
    fileDownloads.set(file.url, fetch(file.url).then(response => {
      if (!response.ok) throw new Error('HTTP ' + response.status);
      return response.text();
    }).catch(error => { fileDownloads.delete(file.url); throw error; }));
  }
  const stillSelected = () => request === fileRequest && current === owner && $('#viewer').open && selectedFile === file;
  try {
    file.text = await fileDownloads.get(file.url);
    if (stillSelected()) renderFile(path);
  } catch (error) {
    if (stillSelected()) modal(path,
      '<p role="alert">' + (language === 'en' ? 'Could not load this file.' : '文件加载失败。') + '</p>' +
      `<button class="report-link" data-report-file="${esc(path)}">${language === 'en' ? 'Retry' : '重试'}</button>`, '', file);
  }
}

